      objects: [
        { dynamic: true, name: "Center.U", type: state.PZ.property.type.NUMBER, step: 0.1, decimals: 3, value: 0 },
        { dynamic: true, name: "Center.V", type: state.PZ.property.type.NUMBER, step: 0.1, decimals: 3, value: 0 },
